#!/usr/bin/env bash
# Run this from the ROOT of your React Native project (where package.json lives).
set -e
echo "Fixing critical bugs + wiring appointments to the real backend contract..."

echo "  screens/SetReminderScreen.js"
mkdir -p "$(dirname 'screens/SetReminderScreen.js')"
echo '' | base64 --decode > 'screens/SetReminderScreen.js'

echo "  screens/ConfirmAppointmentScreen.js"
mkdir -p "$(dirname 'screens/ConfirmAppointmentScreen.js')"
echo '' | base64 --decode > 'screens/ConfirmAppointmentScreen.js'

echo "  package.json"
mkdir -p "$(dirname 'package.json')"
echo '' | base64 --decode > 'package.json'

echo "  app.json"
mkdir -p "$(dirname 'app.json')"
echo '' | base64 --decode > 'app.json'

echo "Installing expo-notifications..."
npx expo install expo-notifications

echo ""
echo "Done."
